local TranslateApi = "/user/api/v1/translate"

function WebService:CTryTranslate(text, callback, sourceLanguage, targetLanguages)
    sourceLanguage = sourceLanguage or Lang:getLang()
    local body = {
        sourceLanguage = sourceLanguage,
        targetLanguages = targetLanguages or { sourceLanguage },
        text = { text },
    }
    WebService.asyncPost(TranslateApi, {}, body, function(data, code)
        if callback then
            callback(data, code)
        end
    end)
end